from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1]
data=json.loads((ROOT/'scripts/data/malaysia-natural-earth.geojson').read_text('utf-8'))
def point(lon,lat): return ((lon-98.8)*46+25,(7.6-lat)*46+20)
paths=[]
for polygon in data['geometry']['coordinates']:
 for ring in polygon:
  pts=[point(*coord[:2]) for coord in ring]
  paths.append('M'+'L'.join(f'{x:.2f},{y:.2f}' for x,y in pts)+'Z')
svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1020 390" fill="currentColor" role="img" aria-label="Malaysia: Peninsular Malaysia to the west, Malaysian Borneo to the east">'+''.join(f'<path d="{d}"/>' for d in paths)+'</svg>'
(ROOT/'assets/icons/malaysia-map.svg').write_text(svg,'utf-8')
for concept in ['a','b']:
 out=ROOT/f'output/v2/prototypes/{concept}';out.mkdir(parents=True,exist_ok=True)
 heading='MALAYSIA' if concept=='a' else 'A world<br>between.'
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><link rel="icon" href="/assets/icons/favicon.svg"><title>Prototype {concept.upper()} — Malaysia</title><link rel="stylesheet" href="../prototype.css"><script defer src="/assets/vendor/gsap.min.js"></script><script defer src="/assets/vendor/ScrollTrigger.min.js"></script><script type="module" src="../prototype.js"></script></head><body class="concept-{concept}"><header><a href="/">Between Places.</a><span>{'Atlas into cinema' if concept=='a' else 'Surreal landscape passage'}</span><button type="button" id="pause" aria-pressed="false">Pause movement</button></header><main><section class="experiment"><div class="stage"><div class="map">{svg}<nav aria-label="Map destinations"><a href="/destinations/langkawi/">Langkawi</a><a href="/destinations/george-town/">George Town</a><a href="/destinations/kuala-lumpur/">Kuala Lumpur</a><a href="/destinations/sabah/">Sabah · Borneo</a></nav><p>Peninsular Malaysia <span>South China Sea</span> Malaysian Borneo</p></div><div class="portal"><img src="/assets/images/{'kuala-lumpur' if concept=='a' else 'kinabalu'}-2000.webp" width="2000" height="1344" alt="{'Kuala Lumpur skyline at dusk' if concept=='a' else 'Mount Kinabalu in Sabah'}"></div><h1>{heading}</h1><div class="invitation"><p>{'Two lands. A sea between. Four ways of looking.' if concept=='a' else 'From a point on the map, into another atmosphere.'}</p><a href="#arrival">Scroll into the landscape ↓</a></div></div></section><section id="arrival"><h2>{'The city rises.' if concept=='a' else 'Across the sea. Above the forest.'}</h2><p>{'Kuala Lumpur, Peninsular Malaysia' if concept=='a' else 'Mount Kinabalu, Sabah, Malaysian Borneo'}. Authentic photographs, imagined transitions.</p><a href="/destinations/{'kuala-lumpur' if concept=='a' else 'sabah'}/">Read the destination ↗</a><a href="https://ismailstudio.my/">Made by Ismail Studio ↗</a><p>Photography: {'Esmonde Yong' if concept=='a' else 'EJ Yao'} / Unsplash. Geographic shapes: Natural Earth, public domain. Decorative portal geometry is original interface artwork.</p></section></main></body></html>'''
 (out/'index.html').write_text(html,'utf-8')
base=ROOT/'output/v2/prototypes'
(base/'prototype.css').write_text('''@font-face{font-family:Manrope;src:url(/assets/fonts/manrope.woff2)}@font-face{font-family:Barlow;src:url(/assets/fonts/barlow-condensed.woff2)}*{box-sizing:border-box}body{margin:0;background:#081716;color:#e5e4c9;font-family:Manrope,sans-serif}a{color:inherit}button{font:inherit;background:#e5e4c9;border:0;color:#081716;padding:12px}header{height:90px;display:flex;align-items:center;justify-content:space-between;padding:24px 3vw;position:absolute;z-index:5;inset:0 0 auto}header a{text-decoration:none;font-size:20px}header span{font-size:14px}.stage{height:calc(100svh - 1px);position:relative;overflow:hidden;padding:3vw}.map{position:absolute;top:20%;left:10%;width:80%;color:#c6d597}.map svg{width:100%;height:auto}.map nav{z-index:4;display:flex;justify-content:space-around;position:absolute;inset:52% 0 auto;gap:18px}.map nav a{font-size:14px;background:#081716;padding:12px}.map p{display:flex;justify-content:space-between;font-size:13px}.map p span{font-style:italic}h1{pointer-events:none;font-family:Barlow,sans-serif;font-weight:600;font-size:25vw;letter-spacing:-.03em;line-height:.8;position:absolute;bottom:10%;left:2%;margin:0;z-index:2}.portal{position:absolute;width:19vw;height:24vw;right:11%;top:20%;overflow:hidden}.portal img{width:100%;height:100%;object-fit:cover}.invitation{position:absolute;bottom:3%;inset-inline:3%;display:flex;justify-content:space-between;z-index:3;font-size:14px}.concept-b{background:#092b36;color:#eff2e8}.concept-b .portal{width:60vw;height:60vw;left:20%;top:30%;border-radius:50%;z-index:0}.concept-b .map{z-index:1;width:60%;left:20%;top:12%}.concept-b .map svg{opacity:.85}.concept-b h1{font-family:Georgia,serif;font-weight:normal;font-style:italic;font-size:11vw;line-height:.9;bottom:20%;left:7%}.concept-b .map nav{top:36%}.concept-b .map nav a{background:#092b36}.concept-b .map p{margin-top:-20px}#arrival{padding:10vw 5vw;min-height:60vh;background:#dce4d6;color:#092b36}h2{font-size:clamp(32px,5vw,80px);max-width:1000px}#arrival a{display:inline-block;padding:16px;margin-right:18px;border:1px solid}#arrival p{max-width:65ch;line-height:1.7}.live .experiment{height:230svh}.live .stage{position:sticky;top:0}@media(max-width:700px){header span{display:none}.map{width:110%;left:-5%;top:25%}.map nav{inset:100% 8% auto;flex-wrap:wrap;justify-content:center;gap:4px}.map p{padding:0 8%;font-size:11px}.map p span{display:none}.portal{top:18%;right:9%;width:30vw;height:39vw}h1{bottom:17%;font-size:25vw}.invitation{display:block;bottom:3%;line-height:1.6}.concept-b .map{width:96%;left:2%;top:18%}.concept-b .map nav{top:95%}.concept-b .portal{width:130vw;height:130vw;left:-15%;top:42%}.concept-b h1{font-size:19vw;bottom:23%}.concept-b .map p{display:none}}''','utf-8')
(base/'prototype.js').write_text('''const gsap=window.gsap, ST=window.ScrollTrigger;gsap.registerPlugin(ST);const media=matchMedia('(prefers-reduced-motion: reduce)');let ctx;const pause=document.querySelector('#pause');function setup(){ctx?.revert();document.body.classList.remove('live');if(media.matches||pause.getAttribute('aria-pressed')==='true')return;document.body.classList.add('live');ctx=gsap.context(()=>{const a=document.body.classList.contains('concept-a');const tl=gsap.timeline({scrollTrigger:{trigger:'.experiment',start:'top top',end:'bottom bottom',scrub:true},defaults:{ease:'none'}});tl.to('.map',{scale:a?3:.6,yPercent:a?-70:-80,autoAlpha:0,duration:1},0).to('.portal',{scale:a?6:2.1,xPercent:a?-115:0,yPercent:a?25:-12,borderRadius:a?'0%':'0%',duration:1},0).to('h1',{yPercent:-160,autoAlpha:0,duration:.75},.15).to('.invitation',{autoAlpha:0,duration:.2},.7)});ST.refresh()}pause.addEventListener('click',()=>{const p=pause.getAttribute('aria-pressed')!=='true';pause.setAttribute('aria-pressed',p);pause.textContent=p?'Resume movement':'Pause movement';setup()});media.addEventListener('change',setup);await document.fonts.ready;setup();document.documentElement.dataset.ready='true';''','utf-8')
print('Generated accurate map and two contrasting local prototypes.')
